INSERT INTO verses (id, ref, book, chapter, verse, text, text_normalized, testament, translation_key, dialect, audio_r2_key, audio_public_url, created_at, updated_at) VALUES
(47861, 'Joshua 6:5', 'Joshua', 6, 5, 'بیا دې هغوی په لوړ اواز سره سرني ووهي. څنګه چې تاسو هغه واورئ، ټول خلک دې په لوړ اواز چیغې ووهي، نو د ښار دېوالونه به راپرېوځي. بیا به ټول لښکر مخامخ ښار ته ننوځي.»', 'بیا دې هغوی په لور اواز سره سرنی ووهی. چنګه چې تاسو هغه واوری، تول خلک دې په لور اواز چیغې ووهی، نو د شار دېوالونه به راپرېوجی. بیا به تول لشکر مخامخ شار ته ننوجی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_5.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47862, 'Joshua 6:6', 'Joshua', 6, 6, 'یوشع کاهنان راوغوښتل او هغوی ته یې وویل: «د لوظ صندوق واخلئ او اووه تنه د سرنیو سره د هغه په مخکې حرکت وکړئ.»', 'یوشع کاهنان راوغوشتل او هغوی ته یې وویل: «د لوظ صندوق واخلی او اووه تنه د سرنیو سره د هغه په مخکې حرکت وکری.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_6.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47863, 'Joshua 6:7', 'Joshua', 6, 7, 'بیا هغه قوم ته حکم وکړ: «د ښار څخه ګردچاپېره وګرځئ او وسله وال ساتونکي دې د څښتن د لوظ د صندوق په مخکې روان وي.»', 'بیا هغه قوم ته حکم وکر: «د شار چخه ګردچاپېره وګرجی او وسله وال ساتونکی دې د چشتن د لوظ د صندوق په مخکې روان وی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_7.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47864, 'Joshua 6:8', 'Joshua', 6, 8, 'څنګه چې یوشع قوم ته وینا وکړه، هغه اووه کاهنان چې سرني یې وړل هغوی مخکې روان شول، خپل سرني یې وهل او د څښتن د لوظ صندوق د هغوی پسې ؤ.', 'چنګه چې یوشع قوم ته وینا وکره، هغه اووه کاهنان چې سرنی یې ورل هغوی مخکې روان شول، خپل سرنی یې وهل او د چشتن د لوظ صندوق د هغوی پسې و.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47865, 'Joshua 6:9', 'Joshua', 6, 9, 'وسله وال ساتونکي د هغو کاهنانو په مخکې چې سرني یې وهل روان وو او شاتنۍ ساتونکې ډله د صندوق پسې روانه وه. په دې ټول وخت کې سرني وهل کېدل.', 'وسله وال ساتونکی د هغو کاهنانو په مخکې چې سرنی یې وهل روان وو او شاتنی ساتونکې دله د صندوق پسې روانه وه. په دې تول وخت کې سرنی وهل کېدل.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47866, 'Joshua 6:10', 'Joshua', 6, 10, 'خو یوشع په قوم باندې امر وکړ: «چیغې مه وهئ، ترڅو پورې چې زه تاسو ته امر ونه کړم تاسو به هېڅ نه وایئ.»', 'خو یوشع په قوم باندې امر وکر: «چیغې مه وهی، ترچو پورې چې زه تاسو ته امر ونه کرم تاسو به هېچ نه وایی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_10.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47867, 'Joshua 6:11', 'Joshua', 6, 11, 'نو یوشع وویل چې د څښتن د لوظ صندوق دې یوځل د ښار څخه ګردچاپېره وګرځوي. بیا ټول خلک بېرته کمپ ته راغلل او هلته یې شپه تېره کړه.', 'نو یوشع وویل چې د چشتن د لوظ صندوق دې یوجل د شار چخه ګردچاپېره وګرجوی. بیا تول خلک بېرته کمپ ته راغلل او هلته یې شپه تېره کره.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_11.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47868, 'Joshua 6:12', 'Joshua', 6, 12, 'یوشع سهار وختي پاڅېده او کاهنانو او خپلو کسانو ته یې هماغه امر وکړ. نو هغو کاهنانو چې د لوظ د صندوق د وړلو حکم ورته شوی ؤ هغه په خپلو اوږو باندې کېښود.', 'یوشع سهار وختی پاچېده او کاهنانو او خپلو کسانو ته یې هماغه امر وکر. نو هغو کاهنانو چې د لوظ د صندوق د ورلو حکم ورته شوی و هغه په خپلو اوزو باندې کېشود.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47869, 'Joshua 6:13', 'Joshua', 6, 13, 'بیا هغوی لکه د تېرې ورځې په شان په هماغه ترتیب سره د ښار ګردچاپېره وګرځېدل. لومړی هغه ساتونکي چې مخکې روان وو، بیا هغه کاهنان چې د ګرځېدلو په حال کې به یې هر وخت سرني وهل، ورپسې هغه کاهنان چې د څښتن د لوظ صندوق یې وړلو او په اخره کې شاتنۍ ساتونکې ډله.', 'بیا هغوی لکه د تېرې ورجې په شان په هماغه ترتیب سره د شار ګردچاپېره وګرجېدل. لومری هغه ساتونکی چې مخکې روان وو، بیا هغه کاهنان چې د ګرجېدلو په حال کې به یې هر وخت سرنی وهل، ورپسې هغه کاهنان چې د چشتن د لوظ صندوق یې ورلو او په اخره کې شاتنی ساتونکې دله.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47870, 'Joshua 6:14', 'Joshua', 6, 14, 'نو په دوهمه ورځ هغوی بیا یوځل د ښار څخه ګردچاپېره وګرځېدل او وروسته کمپ ته راستانه شول. هغوی شپږ ورځې دا کار وکړ.', 'نو په دوهمه ورج هغوی بیا یوجل د شار چخه ګردچاپېره وګرجېدل او وروسته کمپ ته راستانه شول. هغوی شپز ورجې دا کار وکر.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_14.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47871, 'Joshua 6:15', 'Joshua', 6, 15, 'په اوومه ورځ هغوی سهار وختي پاڅېدل او په همدې ډول اووه ځلې د ښار څخه ګردچاپېره وګرځېدل. دا یوازېنۍ ورځ وه چې هغوی اووه ځلې داسې وکړل.', 'په اوومه ورج هغوی سهار وختی پاچېدل او په همدې دول اووه جلې د شار چخه ګردچاپېره وګرجېدل. دا یوازېنی ورج وه چې هغوی اووه جلې داسې وکرل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_15.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47872, 'Joshua 6:16', 'Joshua', 6, 16, 'په اووم ځل کله چې کاهنانو سرني ووهل، یوشع په قوم باندې امر وکړ: «چیغې ووهئ! ځکه چې څښتن دا ښار تاسو ته درکړی دی!', 'په اووم جل کله چې کاهنانو سرنی ووهل، یوشع په قوم باندې امر وکر: «چیغې ووهی! جکه چې چشتن دا شار تاسو ته درکری دی!', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_16.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47873, 'Joshua 6:17', 'Joshua', 6, 17, 'دا ښار او هرڅه چې په کې دي هغه باید څښتن ته د نذرانې په توګه بیخي له منځه یووړل شي. یوازې راحاب بدلمنه او د هغې کورنۍ دې ژوندي پاتې شي، ځکه چې هغې زمونږ جاسوسان پټ کړي وو.', 'دا شار او هرچه چې په کې دی هغه باید چشتن ته د نذرانې په توګه بیخی له منجه یوورل شی. یوازې راحاب بدلمنه او د هغې کورنی دې ژوندی پاتې شی، جکه چې هغې زمونز جاسوسان پت کری وو.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_17.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47874, 'Joshua 6:18', 'Joshua', 6, 18, 'خو تاسو باید هېڅ شی چې له منځه وړل کیږي وانخلئ، که تاسو یې واخلئ، نو د اسراییلو په کمپ باندې به مصیبت او تباهي راولئ.', 'خو تاسو باید هېچ شی چې له منجه ورل کیزی وانخلی، که تاسو یې واخلی، نو د اسراییلو په کمپ باندې به مصیبت او تباهی راولی.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_18.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47875, 'Joshua 6:19', 'Joshua', 6, 19, 'ټول سپین زر او سره زر او د برنجو او اوسپنې شیان په ځانګړې توګه د څښتن دي او د هغه په خزانه کې باید کېښودل شي.»', 'تول سپین زر او سره زر او د برنجو او اوسپنې شیان په جانګرې توګه د چشتن دی او د هغه په خزانه کې باید کېشودل شی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_19.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47876, 'Joshua 6:20', 'Joshua', 6, 20, 'نو کاهنانو سرني ووهل. څنګه چې قوم د سرنیو غږ واورېده، هغوی په لوړ اواز چیغې ووهلې او ناڅاپه د اریحا د ښار دېوالونه راولوېدل. نو بیا ټول لښکر نېغ په نېغه غونډۍ ته وروخوت. هغوی ښار ته ننوتل او هغه یې ونیوه.', 'نو کاهنانو سرنی ووهل. چنګه چې قوم د سرنیو غز واورېده، هغوی په لور اواز چیغې ووهلې او ناچاپه د اریحا د شار دېوالونه راولوېدل. نو بیا تول لشکر نېغ په نېغه غوندی ته وروخوت. هغوی شار ته ننوتل او هغه یې ونیوه.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_20.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47877, 'Joshua 6:21', 'Joshua', 6, 21, 'هغوی په خپلو تورو باندې په ښار کې ټول خلک یعنې سړي، ښځې، ځوان او زوړ ټول ووژل. همدارنګه هغوی غویان، پسونه او خره هم ووژل.', 'هغوی په خپلو تورو باندې په شار کې تول خلک یعنې سری، شجې، جوان او زور تول ووژل. همدارنګه هغوی غویان، پسونه او خره هم ووژل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_21.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47878, 'Joshua 6:22', 'Joshua', 6, 22, 'نو بیا یوشع هغو دوو کسانو ته چې جاسوسي یې کړې وه وویل: «تاسو د هغې بدلمنې کور ته ورننوځئ او لکه څنګه چې مو د هغې سره وعده کړې وه، هغه او د هغې کورنۍ راوباسئ.»', 'نو بیا یوشع هغو دوو کسانو ته چې جاسوسی یې کرې وه وویل: «تاسو د هغې بدلمنې کور ته ورننوجی او لکه چنګه چې مو د هغې سره وعده کرې وه، هغه او د هغې کورنی راوباسی.»', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_22.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47879, 'Joshua 6:23', 'Joshua', 6, 23, 'نو هغوی لاړل او راحاب یې د هغې د مور او پلار، ورونو او د هغې د ټولې کورنۍ سره راوویستل. هغوی د راحاب ټوله کورنۍ یو خوندي ځای ته چې د اسراییلو کمپ ته نژدې ؤ یووړله.', 'نو هغوی لارل او راحاب یې د هغې د مور او پلار، ورونو او د هغې د تولې کورنی سره راوویستل. هغوی د راحاب توله کورنی یو خوندی جای ته چې د اسراییلو کمپ ته نژدې و یوورله.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_23.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47880, 'Joshua 6:24', 'Joshua', 6, 24, 'بیا د اسراییلو لښکرو ټول ښار د هرڅه سره وسوځاوه، خو هغوی سپین زر او سره زر او د برنجو او اوسپنې شیان د څښتن د کور په خزانه کې کېښودل.', 'بیا د اسراییلو لشکرو تول شار د هرچه سره وسوجاوه، خو هغوی سپین زر او سره زر او د برنجو او اوسپنې شیان د چشتن د کور په خزانه کې کېشودل.', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_24.mp3', 'https://drive.google.com/uc?id=1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY&export=download', 1761237844, 1761237844),
(47881, 'Joshua 6:25', 'Joshua', 6, 25, 'خو یوشع د راحاب بدلمنې او د هغې د کورنۍ او ټولو خپلوانو ژوند وژغوره، ځکه چې هغې هغه جاسوسان پټ کړي وو چې یوشع اریحا ته لېږلي وو. (د هغې اولاده تر نن ورځې پورې په اسراییلو کې اوسیږي.)', 'خو یوشع د راحاب بدلمنې او د هغې د کورنی او تولو خپلوانو ژوند وژغوره، جکه چې هغې هغه جاسوسان پت کری وو چې یوشع اریحا ته لېزلی وو. (د هغې اولاده تر نن ورجې پورې په اسراییلو کې اوسیزی.)', 'OT', 'afghan2023', 'afghan', 'audio/afghan2023/Joshua_6_25.mp3', 'https://drive.google.com/file/d/1_v_gsp-7e90or0oB7fEzUpqKwm2WPDYY/preview', 1761237844, 1761237844),
(47882, 'Joshua 6:26', 'Joshua', 6, 26, 'کله چې اریحا ورانه شوه، نو یوشع په کلکه خبرداری ورکړ: «هرڅوک چې د اریحا د ښار د بیا ودانولو هڅه وکړي، څښتن به په هغه باندې لعنت ووایي: هرڅوک چې کېږدي بنیاد د هغه نو له لاسه وربه کړي خپل مشر زوی هرڅوک چې جوړې کړي د هغه دروازې نو له لاسه وربه کړي خپل کشر زوی»', 'کله چې اریحا ورانه شوه، نو یوشع په کلکه خبرداری ورکر: «هرچوک چې د اریحا د شار د بیا ودانولو هچه وکری، چشتن به په هغه باندې لعنت ووایی: هرچوک چې کېزدی بنیاد د هغه نو له لاسه وربه کری خپل مشر زوی هرچوک چې جورې کری د هغه دروازې نو له لاسه وربه کری خپل کشر زوی»', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
(47883, 'Joshua 6:27', 'Joshua', 6, 27, 'نو څښتن د یوشع سره مل ؤ او د هغه شهرت په ټول هېواد کې خپور شو.', 'نو چشتن د یوشع سره مل و او د هغه شهرت په تول هېواد کې خپور شو.', 'OT', 'afghan2023', 'afghan', '', '', 1761237844, 1761237844),
